mapper.select:
SELECT * FROM ( select T2.TARGET_TYPE targetType, T2.TRADER trader, CASE WHEN (T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND T1.PS IN (#{PS_T93},#{PS_T94})) THEN NVL(T3.PLEDGE_NUMBER,0) - NVL(S.MARCH_QTY_EN,0) ELSE NVL(T1.ENTRUST_NUM,0) - NVL(S.MARCH_QTY_EN,0) END remainEntrustNum, CASE WHEN (T1.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND T1.PS IN (#{PS_T93},#{PS_T94})) THEN NVL(T3.PLEDGE_NUMBER,0) - NVL(S.MARCH_QTY_EN,0) ELSE NVL(T1.ENTRUST_AMT,0) - NVL(S.MARCH_AMT_EN,0) END remainEntrustAmt, T1.* from ETR_ENTRUST T1 left join ETR_ENTRUST_ADD T2 ON T1.ENTRUST_ID = T2.ENTRUST_ID LEFT JOIN (SELECT ENTRUNST_TRADE_ID, NVL(SUM(MARCH_QTY_EN), 0) MARCH_QTY_EN, NVL(SUM(MARCH_AMT_EN), 0) MARCH_AMT_EN FROM SETTLE_TRANS_DATA_TOTAL_MATCH GROUP BY ENTRUNST_TRADE_ID) S ON S.ENTRUNST_TRADE_ID = T1.ENTRUST_ID LEFT JOIN ETR_PLEDGE T3 ON T3.ENTRUST_ID = T1.ENTRUST_ID AND T3.FINPROD_ID = T1.FINPROD_ID
AND (T1.ENTRUST_ID IN
null) or T1.ENTRUST_ID in (
#{item,jdbcType=VARCHAR} )
AND T1.ENTRUST_ID = #{entrustId}
AND T1.ENTRUST_STATUS = #{ENTRUST_STATUS_03}
) T WHERE (T.FINPROD_TYPE2 IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND T.remainEntrustNum > 0) OR (T.FINPROD_TYPE2 NOT IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND T.targetType = #{TARGET_CLASS_01} AND T.remainEntrustNum > 0) OR (T.FINPROD_TYPE2 NOT IN (#{FINPROD_TYPE_TG_F02}, #{FINPROD_TYPE_TG_F03}) AND T.targetType = #{TARGET_CLASS_02} AND T.remainEntrustAmt > 0)

SELECT DISTINCT TRADE_ID_TG FROM SETTLE_TRANS_DATA_TOTAL t1 INNER JOIN SETTLE_TRANS_TG_MAPPING t2 ON t1.TRADE_ID = t2.TRADE_ID
t1.APPLY_TRADE_ID = #{tradeId,jdbcType=VARCHAR}
and t1.PS = #{ps,jdbcType=VARCHAR}

select A.* from SETTLE_TRANS_DATA A INNER JOIN SETTLE_TRANS_DATA_TOTAL B ON A.APPLY_TRADE_ID = B.APPLY_TRADE_ID AND A.DEAL_DATE = B.DEAL_DATE AND A.SEAT_NUMBER = B.SEAT_NUMBER AND A.PS = B.PS AND A.FINPROD_TYPE2 = B.FINPROD_TYPE2
B.SEQ_ID = #{seqId,jdbcType=VARCHAR}
AND A.CJBH = #{tradeIdRaw,jdbcType=VARCHAR}
UNION select A.* from SETTLE_TRANS_DATA A INNER JOIN SETTLE_TRANS_DATA_TOTAL B ON A.DEAL_DATE = B.DEAL_DATE AND A.SEAT_NUMBER = B.SEAT_NUMBER AND A.PS = B.PS AND A.FINPROD_TYPE2 = B.FINPROD_TYPE2
B.SEQ_ID = #{seqId,jdbcType=VARCHAR} AND A.PS IN ('T46','T97')
AND A.CJBH = #{tradeIdRaw,jdbcType=VARCHAR}

mapper.delete:
delete from SETTLE_TRANS_DATA_TOTAL_MATCH T
 where T.SEQ_NO = #{totalSeqId}
   AND T.ENTRUNST_TRADE_ID = #{entrunstId}

mapper.select:
select NVL(SUM(T.MARCH_QTY),0)
  from SETTLE_TRANS_DATA_TOTAL_MATCH T
 WHERE T.SEQ_NO = #{totalSeqId}

select 'N' isTotalDeal, E.FINPROD_TYPE2 finprodType2, E.TRADE_ID tradeIdTgDetail, C.PS ps, C.SEQ_ID seqTotalId, F.PORTFOLIO_ID portfolioId,
A.* from SETTLE_TRANS_TG_MAPPING A INNER JOIN SETTLE_TRANS_DATA B ON A.TRADE_ID = B.TRADE_ID INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON B.APPLY_TRADE_ID = C.APPLY_TRADE_ID AND B.DEAL_DATE = C.DEAL_DATE AND B.SEAT_NUMBER = C.SEAT_NUMBER INNER JOIN SETTLE_TRANS_DATA_TOTAL_MATCH D ON C.SEQ_ID = D.SEQ_NO INNER JOIN TRD_PRODUCT_DEAL E ON E.TRADE_ID = A.TRADE_ID_TG INNER JOIN TRD_PRODUCT_DEAL_ADD F ON E.TRADE_ID = F.TRADE_ID AND F.ENTRUST_ID = D.ENTRUNST_TRADE_ID WHERE A.TG_DATA_STATUS = #{tgDataStatus}
AND C.TRADE_ID_RAW IS NULL
AND D.SEQ_NO = #{seqNo} AND D.ENTRUNST_TRADE_ID = #{entrunstId}
AND D.MATCH_CLASS = #{matchClass}
union select 'N' isTotalDeal, E.FINPROD_TYPE2 finprodType2, E.TRADE_ID tradeIdTgDetail, C.PS ps, C.SEQ_ID seqTotalId, F.PORTFOLIO_ID portfolioId,
A.* from SETTLE_TRANS_TG_MAPPING A INNER JOIN SETTLE_TRANS_DATA B ON A.TRADE_ID = B.TRADE_ID INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON B.APPLY_TRADE_ID = C.APPLY_TRADE_ID AND B.DEAL_DATE = C.DEAL_DATE AND B.SEAT_NUMBER = C.SEAT_NUMBER AND B.CJBH = C.TRADE_ID_RAW INNER JOIN SETTLE_TRANS_DATA_TOTAL_MATCH D ON C.SEQ_ID = D.SEQ_NO INNER JOIN TRD_PRODUCT_DEAL E ON E.TRADE_ID = A.TRADE_ID_TG INNER JOIN TRD_PRODUCT_DEAL_ADD F ON E.TRADE_ID = F.TRADE_ID AND F.ENTRUST_ID = D.ENTRUNST_TRADE_ID WHERE A.TG_DATA_STATUS = #{tgDataStatus} AND D.SEQ_NO = #{seqNo} AND C.TRADE_ID_RAW IS NOT NULL AND D.ENTRUNST_TRADE_ID = #{entrunstId}
AND D.MATCH_CLASS = #{matchClass}
union select 'Y' isTotalDeal, E.FINPROD_TYPE2 finprodType2, E.TRADE_ID tradeIdTgDetail, C.PS ps, C.SEQ_ID seqTotalId, F.PORTFOLIO_ID portfolioId, A.* from SETTLE_TRANS_TG_MAPPING A INNER JOIN SETTLE_TRANS_DATA B ON A.TRADE_ID = B.TRADE_ID INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON B.DEAL_DATE = C.DEAL_DATE AND B.SEAT_NUMBER = C.SEAT_NUMBER INNER JOIN SETTLE_TRANS_DATA_TOTAL_MATCH D ON C.SEQ_ID = D.SEQ_NO INNER JOIN TRD_PRODUCT_DEAL E ON E.TOTLE_TRADE_ID = A.TRADE_ID_TG INNER JOIN TRD_PRODUCT_DEAL_ADD F ON E.TRADE_ID = F.TRADE_ID AND F.ENTRUST_ID = D.ENTRUNST_TRADE_ID WHERE A.TG_DATA_STATUS = #{tgDataStatus} AND D.SEQ_NO = #{seqNo} AND D.ENTRUNST_TRADE_ID = #{entrunstId}
AND D.MATCH_CLASS = #{matchClass}
UNION select 'Y' isTotalDeal, E.FINPROD_TYPE2 finprodType2, E.TRADE_ID tradeIdTgDetail, C.PS ps, C.SEQ_ID seqTotalId, F.PORTFOLIO_ID portfolioId, A.* from SETTLE_TRANS_TG_MAPPING A INNER JOIN SETTLE_TRANS_DATA B ON A.TRADE_ID = B.TRADE_ID INNER JOIN SETTLE_TRANS_DATA_TOTAL C ON B.DEAL_DATE = C.DEAL_DATE AND B.SEAT_NUMBER = C.SEAT_NUMBER INNER JOIN SETTLE_TRANS_DATA_TOTAL_MATCH D ON C.SEQ_ID = D.SEQ_NO INNER JOIN TRD_PRODUCT_DEAL E ON E.TOTLE_TRADE_ID = A.TRADE_ID_TG INNER JOIN TRD_PRODUCT_DEAL_ADD F ON E.TRADE_ID = F.TRADE_ID AND F.ENTRUST_ID = D.ENTRUNST_TRADE_ID WHERE A.TG_DATA_STATUS = #{tgDataStatus} AND D.SEQ_NO = #{seqNo} AND D.ENTRUNST_TRADE_ID = #{entrunstId}
AND D.MATCH_CLASS = #{matchClass}

