    AND SEC_ACCT_ID = #{secManageAcctId,jdbcType=VARCHAR}

select
    NVL(FSCR.SCALE, 0)
from FIN_STDSEC_CONVERSE_RADIO FSCR
where FSCR.FINPROD_ID = #{finprodId, jdbcType=VARCHAR}
  AND FSCR.BRANCH = '0'
  AND FSCR.VDATE  <= #{vdate, jdbcType=DATE}
  AND NOT EXISTS (SELECT 1
                  FROM FIN_STDSEC_CONVERSE_RADIO FSCRINNER
                  WHERE FSCRINNER.FINPROD_ID = FSCR.FINPROD_ID
                    AND FSCRINNER.BRANCH ='0'
                    AND FSCRINNER.VDATE <= #{vdate, jdbcType=DATE}
                    AND FSCRINNER.VDATE > FSCR.VDATE
    )
